#!/usr/bin/bash
# Lucent visual design: the packages and caches behind the look shipped in
# system_files/ (Plasma theme, window decoration, icons, launcher, wallpaper).
# Called from build.sh; sources and licenses are listed in THIRD_PARTY.md.
# The theme assets themselves are generated by design/*.py from
# docs/mockups/ and committed, so nothing here renders artwork.
set -xeuo pipefail

DNF=$(command -v dnf5 || command -v dnf)
DNF_OPTS=(-y --setopt=install_weak_deps=False)
FEDORA=$(rpm -E %fedora)

# Papirus (Fedora packages, GPL-3.0): every icon the Lucent icon theme
# doesn't draw itself (/usr/share/icons/Lucent inherits Papirus-Light,
# Lucent-Dark inherits Papirus-Dark; Fedora ships those two variants as
# separate packages, without them the chain falls through to Breeze and dark
# toolbars get dark glyphs).
"$DNF" "${DNF_OPTS[@]}" install papirus-icon-theme papirus-icon-theme-light papirus-icon-theme-dark

# Papirus's folders (what GTK apps show for folders Lucent doesn't draw) in
# Pebble Drift's indigo: build_files/papirus-indigo.sh, tested first on a
# fake tree. Then prove it took on the real one.
/ctx/build_files/papirus-indigo-test.sh /ctx/build_files/papirus-indigo.sh
/ctx/build_files/papirus-indigo.sh /usr/share/icons
for icon in 16x16/places/folder 22x22/places/folder 64x64/places/folder 64x64/places/folder-templates; do
    f=$(readlink -f "/usr/share/icons/Papirus/$icon.svg")
    echo "Papirus $icon -> ${f##*/}"
    [[ "$f" == *-indigo* ]] && grep -q -e '#4a5fe0' -e '#8496f5' "$f" || { echo "Papirus $icon is not Drift indigo"; exit 1; }
done
for theme in Papirus Papirus-Light Papirus-Dark; do
    gtk-update-icon-cache -f -q "/usr/share/icons/$theme"
done

# Rounded window corners + hairline outline: KDE-Rounded-Corners (GPL-3.0)
# from its author's COPR. Its builds are tied to one KWin release (the RPM
# release is the KWin version). If no build for this image's KWin exists yet,
# the image still builds; windows then just keep square bottom corners.
curl -fsSL "https://copr.fedorainfracloud.org/coprs/matinlotfali/KDE-Rounded-Corners/repo/fedora-$FEDORA/matinlotfali-KDE-Rounded-Corners-fedora-$FEDORA.repo" \
    -o /etc/yum.repos.d/lucent-roundcorners.repo
kwin_version=$(rpm -q --qf '%{VERSION}' kwin)
if "$DNF" "${DNF_OPTS[@]}" install kwin-effect-roundcorners; then
    built_for=$(rpm -q --qf '%{RELEASE}' kwin-effect-roundcorners)
    if [[ "$built_for" != "$kwin_version".* ]]; then
        echo "WARNING: kwin-effect-roundcorners was built for KWin ${built_for%%.fc*}, image has $kwin_version; leaving it out"
        "$DNF" -y --setopt=clean_requirements_on_remove=False remove kwin-effect-roundcorners
    fi
else
    echo "WARNING: kwin-effect-roundcorners unavailable for Fedora $FEDORA; windows keep square bottom corners"
fi
rm -f /etc/yum.repos.d/lucent-roundcorners.repo

# Widget style for Qt apps: Kvantum (GPL-3.0) with Lucent's SVG theme
# (/usr/share/Kvantum/Lucent, design/gen_kvantum.py), wrapped by Lucent's
# small style plugin (build_files/lucent-style) that fixes Dolphin's path
# bar, toolbar groups and free-space line on top of Kvantum. Login screen:
# SDDM with Lucent's own theme (Fedora 45 defaults to Plasma Login Manager,
# whose greeter is compiled in and can't be themed).
"$DNF" "${DNF_OPTS[@]}" install kvantum sddm sddm-wayland-plasma

# Build the style plugin against this image's Qt, then drop the toolchain
# again (only what this step added; nothing of the base is removed).
rpm -qa --qf '%{NAME}\n' | sort > /tmp/before-style.txt
"$DNF" "${DNF_OPTS[@]}" install gcc-c++ cmake make qt6-qtbase-devel
cmake -S /ctx/build_files/lucent-style -B /tmp/lucent-style -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX=/usr
cmake --build /tmp/lucent-style --parallel
cmake --install /tmp/lucent-style
rpm -qa --qf '%{NAME}\n' | sort > /tmp/after-style.txt
mapfile -t added < <(comm -13 /tmp/before-style.txt /tmp/after-style.txt)
if ((${#added[@]})); then
    "$DNF" -y --setopt=clean_requirements_on_remove=False remove "${added[@]}"
fi
rm -rf /tmp/lucent-style /tmp/before-style.txt /tmp/after-style.txt
ls /usr/lib*/qt6/plugins/styles/liblucentstyle.so
# Both styles must load (offscreen, no display needed).
QT_QPA_PLATFORM=offscreen python3 -c '
from PySide6.QtWidgets import QApplication, QStyleFactory
app = QApplication([])
keys = [k.lower() for k in QStyleFactory.keys()]
assert {"lucent", "lucent-dark", "kvantum", "kvantum-dark"} <= set(keys), keys
for k in ("kvantum", "lucent", "lucent-dark"):
    assert QStyleFactory.create(k) is not None, k
print("Qt styles OK:", keys)'

# Login screen: SDDM (theme in /usr/share/sddm/themes/lucent, settings in
# /usr/lib/sddm/sddm.conf.d/zz-lucent.conf) instead of plasmalogin.
test -f /usr/share/sddm/themes/lucent/Main.qml
systemctl disable plasmalogin.service || true
systemctl enable --force sddm.service

# Flatpak Qt apps follow the light/dark Kvantum theme (per-user path unit).
systemctl --global enable lucent-kvantum-sync.path

# UI font: Figtree (system_files/usr/share/fonts/figtree, SIL OFL) for languages
# it covers, Inter for the rest (lucent-theme font). fontconfig must see it,
# say it covers English and not Russian, and fall back to Inter from it.
fc-cache -f /usr/share/fonts/figtree
fc-list 'Figtree:lang=en' family | grep -q Figtree
if fc-list 'Figtree:lang=ru' family | grep -q Figtree; then echo "Figtree unexpectedly covers Russian"; exit 1; fi
fc-list Figtree style | grep -q Medium
# the first font after Figtree in its fallback list (what Qt uses for a
# missing letter) is Inter
next=$(fc-match -s -f '%{family[0]}\n' Figtree | grep -v -m1 -x Figtree)
[ "$next" = Inter ] || { echo "Figtree falls back to '$next', not Inter"; exit 1; }

# Accents (lucent-theme): every swatch has its Kvantum theme, light and dark.
for t in $(PYTHONPATH=/usr/lib/lucent python3 -P -c \
        'from lucent_theme import accents, theme; print(*(theme.kvantum_theme(a.id) for a in accents.ACCENTS))'); do
    test -f "/usr/share/Kvantum/$t/$t.svg" && test -f "/usr/share/Kvantum/$t/${t}Dark.kvconfig"
done
HOME=/tmp XDG_CONFIG_HOME=/tmp/lucent-theme-check /usr/bin/lucent-theme accents >/dev/null
rm -rf /tmp/lucent-theme-check

# Lock screen: Plasma 6.8 draws it from the desktop shell package; Lucent's
# LockScreenUi.qml replaces the stock one (same authenticator contract). If a
# Plasma update reshapes that package, the stock lock screen stays.
lock=/usr/share/plasma/shells/org.kde.plasma.desktop/contents/lockscreen
if grep -q 'LockScreenUi' "$lock/LockScreen.qml" && [ -f "$lock/PasswordSync.qml" ]; then
    cp /usr/share/lucent/design/lockscreen/LockScreenUi.qml "$lock/LockScreenUi.qml"
else
    echo "WARNING: Plasma's lock screen package changed; keeping the stock lock screen"
fi

# A Windows switcher's launcher shows apps, not admin and developer tools:
# these stay installed but get NoDisplay (also hides them from search). Info
# Center and Firewall stay reachable from System Settings, Help from F1.
for id in firewall-config org.kde.kcharselect org.kde.kdebugsettings org.kde.kdeconnect.sms \
          org.kde.khelpcenter org.kde.kinfocenter org.kde.kmenuedit org.kde.kwalletmanager \
          org.kde.plasma.emojier org.kde.kfind org.kde.partitionmanager kvantummanager; do
    f=/usr/share/applications/$id.desktop
    [ -f "$f" ] || continue
    grep -q '^NoDisplay=true' "$f" || sed -i '0,/^\[Desktop Entry\]/s//[Desktop Entry]\nNoDisplay=true/' "$f"
done

# Icon caches for the generated Lucent themes (Papirus ships its own).
for theme in Lucent Lucent-Dark; do
    gtk-update-icon-cache -f "/usr/share/icons/$theme"
done

# Lucent Plasma packages (plain QML, no build step): fail early if incomplete.
for pkg in /usr/share/plasma/plasmoids/org.lucent.*; do
    test -f "$pkg/metadata.json" && test -f "$pkg/contents/ui/main.qml"
done

# Boot splash: Lucent logo on Drift night (background.png, design/
# render-boot-background.py) + Fedora's spinner frames (plymouth-theme-spinner,
# GPL-2.0-or-later) copied into the lucent theme, then the initramfs is
# rebuilt so Plymouth has the theme before the root filesystem is mounted.
theme=/usr/share/plymouth/themes/lucent
for f in /usr/share/plymouth/themes/spinner/*.png; do
    case "${f##*/}" in watermark.png|background*.png) ;; *) cp -a "$f" "$theme/" ;; esac
done
plymouth-set-default-theme lucent
kver=$(ls /usr/lib/modules | head -n1)
DRACUT_NO_XATTR=1 dracut --no-hostonly --kver "$kver" --reproducible --zstd -v --add ostree \
    -f "/usr/lib/modules/$kver/initramfs.img"
lsinitrd "/usr/lib/modules/$kver/initramfs.img" > /tmp/initramfs.list
grep "plymouth/themes/lucent/lucent.plymouth" /tmp/initramfs.list
grep "plymouth/themes/lucent/background.png" /tmp/initramfs.list
rm /tmp/initramfs.list

# Translations of the Lucent plasmoids (design/po/<domain>.<lang>.po), compiled
# with the wizard's own .mo writer, so the build needs no gettext tools.
for po in /ctx/design/po/*.po; do
    base=${po##*/}
    domain=${base%.*.po}
    lang=${base%.po}
    lang=${lang##*.}
    PYTHONPATH=/usr/lib/lucent python3 -P -c \
        'import sys; from pathlib import Path; from lucent_migrate.i18n import compile_po; compile_po(Path(sys.argv[1]), Path(sys.argv[2]))' \
        "$po" "/usr/share/locale/$lang/LC_MESSAGES/$domain.mo"
done
